import datetime
import logging
import re
from ute_common_abstract_core import logger as core_logger


class DefaultTemporaryLog(object):

    def __init__(self, config):
        self._config = config
        self._app_temporary_log_path = None
        self._ue_temporary_log_path = None

    @property
    def default_dir(self):
        return core_logger.get_logging_path() + "/"

    @property
    def app_temporary_log_path(self):
        return self._app_temporary_log_path

    @property
    def ue_temporary_log_path(self):
        return self._ue_temporary_log_path

    @staticmethod
    def _get_current_time():
        current_time = datetime.datetime.now()
        return current_time.strftime("%Y%m%d%H%M%S")

    def _get_iperf_server_ip(self):
        host = self._get_option_value("client", "-c") or self._get_option_value("bind", "-B")
        if not host:
            logging.info("iperf server did not specify the interface to bind")
            host = "xxx"
        return host

    def _get_iperf_port(self):
        port = self._get_option_value("port", "-p")
        return port

    def _get_option_value(self, option_key, option_str):
        if isinstance(self._config["cmd_options"], dict):
            return self._config["cmd_options"].get(option_key, None)
        if isinstance(self._config["cmd_options"], str):
            regex_str = r"{option}\s*([\d\.]+)\s*".format(option=option_str)
            field_pattern = re.compile(regex_str)
            try:
                return field_pattern.findall(self._config["cmd_options"])[0]
            except IndexError:
                return None

    def _generate_temporary_ue_log_name(self, filename):
        if self._config["mode"] == "client":
            return filename.replace("client", "server")
        if self._config["mode"] == "server":
            return filename.replace("server", "client")

    def generate_temporary_log_path(self):
        """generate a log file for saving iperf log temporarily"""
        app_temporary_log_name = "iperf{version}_{mode}_{host}_{port}_{timestamp}.log".format(
            version=self._config["version"],
            mode=self._config["mode"],
            host=self._get_iperf_server_ip(),
            port=self._get_iperf_port(),
            timestamp=self._get_current_time()
        )
        ue_temporary_log_name = self._generate_temporary_ue_log_name(app_temporary_log_name)
        self._app_temporary_log_path = self.default_dir + app_temporary_log_name
        self._ue_temporary_log_path = self.default_dir + ue_temporary_log_name
